<?php require_once __DIR__ . '/includes/order_service.php'; $caseCode=$_GET['case'] ?? $_POST['case_code'] ?? ''; $case=db_fetch('SELECT pc.id AS case_id, pc.patient_id, pc.case_code, pc.status, pc.doctor_status, p.full_name,p.phone,p.whatsapp,p.city,p.address FROM patient_cases pc JOIN patients p ON p.id=pc.patient_id WHERE pc.case_code=?',[$caseCode]); if(!$case){ public_header('Order Request'); echo '<div class="container py-5">'.empty_state('Case not found.').'</div>'; public_footer(); exit; } $rx=db_fetch('SELECT id FROM prescriptions WHERE case_id=? AND status="approved" ORDER BY id DESC LIMIT 1',[$case['case_id']]); if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $oid=create_order((int)$case['case_id'],$rx?(int)$rx['id']:null,(int)$case['patient_id'],$_POST); redirect('order-success.php?order='.$oid); } public_header('Request Medicine Order'); ?>
<section class="py-5"><div class="container"><div class="card soft-card"><div class="card-body p-4"><h1>Request Medicine Order</h1><p>Case ID: <strong><?= e($caseCode) ?></strong>. Payment method is Cash on Delivery only. Order stays Pending Specialist Verification until doctor approval.</p><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="case_code" value="<?= e($caseCode) ?>"><div class="row g-3"><div class="col-md-6"><label>Name</label><input name="delivery_name" class="form-control" value="<?= e($case['full_name']) ?>" required></div><div class="col-md-6"><label>Phone</label><input name="delivery_phone" class="form-control" value="<?= e($case['phone']) ?>" required></div><div class="col-md-6"><label>WhatsApp</label><input name="delivery_whatsapp" class="form-control" value="<?= e($case['whatsapp']) ?>" required></div><div class="col-md-6"><label>City</label><input name="city" class="form-control" value="<?= e($case['city']) ?>" required></div><div class="col-12"><label>Delivery address</label><textarea name="delivery_address" class="form-control" required><?= e($case['address']) ?></textarea></div><div class="col-12"><label>Notes</label><textarea name="admin_notes" class="form-control"></textarea></div></div><button class="btn btn-teal mt-3">Submit COD Order Request</button></form></div></div></div></section><?php public_footer(); ?>
